//! Drafter pairing profiles from MODEL.toml `[[dflash.profile]]`.
//!
//! One row describes one drafter family a target accepts: its kind, how the
//! engine claims and admits a checkpoint for it, the capture transform, the
//! verify widths, and (for `exact`/`quorum` rows) the full checkpoint identity
//! the drafter's `config.json` must match. The table is generated by
//! `build_profile.rs` from every model directory, so drafter admission is the
//! same in every binary regardless of which kernel targets it compiled.

/// Drafter family of a profile row.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DrafterKind {
    Dflash,
    Dflash2,
    Dspark,
    /// External MTP head checkpoint (for example the Inferact Flash-Next MTP).
    Mtp,
}

/// How the engine decides that a drafter checkpoint belongs to a row.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DrafterAdmission {
    /// Claimed by the DFlash2 family signature (architecture, conv/selector
    /// geometry or tensors). A claimed checkpoint must match one exact row.
    Exact,
    /// Claimed when two of {target depth, draft geometry, capture taps} match,
    /// or by its DFlash2 selector-vocabulary marker. A claimed checkpoint
    /// must match the row exactly, so a one-field mutation fails closed.
    Quorum,
    /// Admitted by the generic DFlash/DSpark validator; no identity pinned.
    Generic,
    /// The engine refuses this pairing; the row exists for launcher discovery.
    Refused,
}

/// Target hidden-state transform a pairing selects for capture.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DrafterCaptureMode {
    /// Copy a contiguous BF16 slice of the residual row.
    ResidualSlice,
    /// FP32 residual targets (Gemma-4 dense): downcast at capture. Declared so
    /// a row can name it; the engine refuses it until the kernel exists.
    ResidualSliceF32Downcast,
    /// Collapse a Qwen4 four-stream residual with its terminal hyper mixer.
    Qwen4HyperProjected,
    /// Collapse a Qwen4 four-stream residual with the next layer's attention
    /// hyperconnection mixer (`layers[t + 1].attn_hyper_connection`).
    Qwen4LayerAttnHc,
    /// Mean of the four Qwen4 hyperconnection streams (incoai FN DFlash2).
    Qwen4HcMean,
}

impl DrafterCaptureMode {
    /// Whether the engine has a capture path for this mode.
    pub fn is_implemented(self) -> bool {
        matches!(
            self,
            Self::ResidualSlice
                | Self::Qwen4HyperProjected
                | Self::Qwen4LayerAttnHc
                | Self::Qwen4HcMean
        )
    }
}

/// Pin on an optional numeric checkpoint field.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum VocabPin {
    Unchecked,
    /// The checkpoint must not declare the field.
    Undeclared,
    /// See the field docs for whether an omitted value inherits.
    Equals(usize),
}

/// Target model identity a row requires at pairing time (`None` = unchecked).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TargetIdentity {
    pub hidden_size: Option<usize>,
    pub residual_width: Option<usize>,
    pub num_layers: Option<usize>,
    /// Accepted target vocabularies (physical and tokenizer-logical).
    pub vocab_sizes: Option<&'static [usize]>,
}

/// Drafter `config.json` identity. Every `Some` field is enforced; `None`
/// leaves the field to the generic validator.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct DrafterIdentity {
    /// `architectures` must be exactly `[architecture]`.
    pub architecture: Option<&'static str>,
    pub model_type: Option<&'static str>,
    pub hidden_size: Option<usize>,
    pub intermediate_size: Option<usize>,
    pub num_hidden_layers: Option<usize>,
    pub num_target_layers: Option<usize>,
    pub num_attention_heads: Option<usize>,
    pub num_key_value_heads: Option<usize>,
    pub head_dim: Option<usize>,
    pub vocab_size: Option<usize>,
    /// `Equals(n)`: the effective draft vocabulary (declared, else
    /// `vocab_size`) is `n`. `Undeclared`: no draft-to-target remap.
    pub draft_vocab_size: VocabPin,
    /// Nested `dflash_config.block_size` (and the resolved block) is this.
    pub block_size: Option<usize>,
    /// The root `block_size` is also explicitly present and equal.
    pub root_block_size_explicit: bool,
    pub mask_token_id: Option<u32>,
    /// Ordered capture taps (`dflash_config.target_layer_ids`).
    pub target_layer_ids: Option<&'static [usize]>,
    pub conv_kernel_size: Option<usize>,
    pub conv_group_size: Option<usize>,
    pub selector_rank: Option<usize>,
    pub selector_top_k: Option<usize>,
    /// `Equals(n)`: declared and `n`. `Undeclared`: absent.
    pub selector_vocab_size: VocabPin,
    /// `dflash_config` may carry no unknown fields.
    pub forbid_unknown_fields: bool,
    pub layer_types: Option<&'static [&'static str]>,
    pub sliding_window: Option<usize>,
    /// Must be declared explicitly with this value.
    pub is_causal: Option<bool>,
    pub tie_word_embeddings: Option<bool>,
    /// Default RoPE with exactly this theta and no scaling parameters.
    pub rope_theta: Option<f32>,
    pub rms_norm_eps: Option<f32>,
    pub hidden_act: Option<&'static str>,
    /// Exact BF16 tensor census size.
    pub tensor_count: Option<usize>,
    /// Exact structural parameter count.
    pub parameter_count: Option<usize>,
    /// Tensors must use bare names (no `model.` prefix).
    pub bare_tensor_names: bool,
}

/// One `[[dflash.profile]]` row.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct DrafterProfile {
    /// Kernel target directory the row was declared in (`kernels/$hw/<model>`).
    pub target_model: &'static str,
    pub name: &'static str,
    pub kind: DrafterKind,
    pub admission: DrafterAdmission,
    /// Passed its Spark acceptance and identity gates. Unqualified exact or
    /// quorum rows stay behind their experimental gate.
    pub qualified: bool,
    /// The launcher's default speculation for this target.
    pub launcher_default: bool,
    pub capture_mode: DrafterCaptureMode,
    /// Physical verify widths `(min, max)` the trained block supports.
    pub verify_k: Option<(usize, usize)>,
    /// One wider experimental verify width (`ATLAS_DFLASH2_WIDTH_16`).
    pub wide_verify_k: Option<usize>,
    /// Proposal vocabulary the drafter's selector is trained over.
    pub proposal_vocab: Option<usize>,
    pub allow_modelopt_nvfp4: bool,
    pub allow_rtncal_w4a4: bool,
    /// Permit an optional low-rank Markov head (`markov_rank > 0`) on this row.
    pub allow_markov: bool,
    pub target: TargetIdentity,
    pub drafter: DrafterIdentity,
}

impl DrafterProfile {
    /// `<target_model>/<name>`, used in admission logs and errors.
    pub fn label(&self) -> String {
        format!("{}/{}", self.target_model, self.name)
    }
}

include!(concat!(env!("OUT_DIR"), "/drafter_profiles.rs"));

/// Every `[[dflash.profile]]` row of every model directory, in model order.
pub fn drafter_profiles() -> &'static [DrafterProfile] {
    DRAFTER_PROFILES
}

/// The rows a kernel target declared.
pub fn drafter_profiles_for(target_model: &str) -> impl Iterator<Item = &'static DrafterProfile> {
    DRAFTER_PROFILES
        .iter()
        .filter(move |profile| profile.target_model == target_model)
}
